-- الأقوال الأولى للمنصة (الإحصاءات تبدأ من الصفر)
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-1', 'sakina-al-qalb', 'published', '2026-10-15T07:00:00Z', '2026-09-01T09:00:00Z', '2026-09-01T09:00:00Z', '{"text":"لَيْسَ كُلُّ هُدُوءٍ رِضًا، وَلَكِنَّ فِي الرِّضَا هُدُوءًا لَا يَهْتَزُّ وَلَوْ عَاصَفَتِ الدُّنْيَا.","plainText":"ليس كل هدوء رضا، ولكن في الرضا هدوءا لا يهتز ولو عاصفت الدنيا.","language":"fusha","author":"شعيب المطوع","topics":["الطمأنينة","التأمّل","الصبر"],"behindTheWords":"كتبتُ هذه الكلمات بعد ليلةٍ شعرتُ فيها أن الصمت الخارجي ليس سوى قناع، وأن السكينة الحقيقية لا تبدأ إلا حين يسلّم القلب أمره لله تمامًا، فلا تعود تقلقه الرياح العابرة.","pairedQuoteId":"quote-2","revisions":[{"id":"rev-1","timestamp":"2026-09-01T09:00:00Z","note":"المسودة الأولى في دفتر الخواطر","textSnippet":"ليس كل صمت رضا.."},{"id":"rev-2","timestamp":"2026-09-10T14:30:00Z","note":"تنقيح العبارة وضبط التشكيل الفصيح","textSnippet":"لَيْسَ كُلُّ هُدُوءٍ رِضًا.."}]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-2', 'darja-hada-al-khatar', 'published', '2026-10-15T07:00:00Z', '2026-09-02T10:15:00Z', '2026-09-02T10:15:00Z', '{"text":"مَاشِي كُلْ سْكَاتْ رَاحَة.. كَايْنْ سْكَاتْ خْنِيقْ، وَكَايْنْ رْضَى يْهَبَّطْ عَلَى قَلْبَكْ الْبَرْدْ حَتَّى لَوْ كَانَتْ الدَّنْيَا تَغْلِي.","plainText":"ماشي كل سكات راحة.. كاين سكات خنيق، وكاين رضى يهبط على قلبك البرد حتى لو كانت الدنيا تغلي.","language":"darja","author":"شعيب المطوع","topics":["الطمأنينة","التأمّل"],"behindTheWords":"الصيغة الجزائرية لنفس المعنى؛ لأن الدارجة تعبّر عن نبرة القلب اليومية بأقصر الطرق وأعمق النبضات الشعبية الصادقة.","pairedQuoteId":"quote-1","revisions":[{"id":"rev-d1","timestamp":"2026-09-02T10:15:00Z","note":"صياغة دارجة عفوية","textSnippet":"ماشي كل سكات راحة.."}]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-3', 'izzat-an-nafs', 'published', '2026-10-14T07:00:00Z', '2026-09-05T18:20:00Z', '2026-09-05T18:20:00Z', '{"text":"عِزَّةُ النَّفْسِ لَيْسَتْ اسْتِكْبَارًا عَلَى النَّاسِ، بَلْ هِيَ أَنْ تَأْنَفَ نَفْسُكَ مِنَ التَّوَسُّلِ لِمَكَانٍ لَمْ يُفْتَحْ لَكَ عَنْ طِيبِ خَاطِرٍ.","plainText":"عزة النفس ليست استكبارا على الناس، بل هي أن تأنف نفسك من التوسل لمكان لم يفتح لك عن طيب خاطر.","language":"fusha","author":"شعيب المطوع","topics":["عزّة النفس","العلاقات"],"behindTheWords":"المكان الذي تحتاج أن تنحني كثيرًا لتدخله، لن يسع قامتك الحقيقية أبدًا. العزة تصونك من ذلّ الرجاء عند الأبواب الموصدة.","pairedQuoteId":"quote-4","revisions":[{"id":"rev-3","timestamp":"2026-09-05T18:20:00Z","note":"الصياغة الأساسية","textSnippet":"عزة النفس ليست استكبارا.."}]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-4', 'darja-bab-el-qadr', 'published', '2026-10-14T07:00:00Z', '2026-09-06T11:00:00Z', '2026-09-06T11:00:00Z', '{"text":"الْبَابْ اللِّي تْحِسْ رُوحَكْ صْغِيرْ بَاشْ تَدْخَلْ لِيهْ.. مَاشِي بَابَكْ، وَالْقَدْرْ يَبْدَا نْهَارْ تَعْرَفْ وَقْتَاشْ تْدُورْ وَتَمْشِي بْلَا مَا تَتْلَفَّتْ.","plainText":"الباب اللي تحس روحك صغير باش تدخل ليه.. ماشي بابك، والقدر يبدا نهار تعرف وقتاش تدور وتمشي بلا ما تتلفت.","language":"darja","author":"شعيب المطوع","topics":["عزّة النفس","العلاقات"],"behindTheWords":"كلمة دارجة موجّهة لكل من يرجو التقدير من أناس لا يرونه. \"القدر غالي وما يتباعش\".","pairedQuoteId":"quote-3","revisions":[{"id":"rev-d4","timestamp":"2026-09-06T11:00:00Z","note":"كتابة النص بالدارجة الجزائرية وتثبيت النبرة","textSnippet":"الباب اللي تحس روحك صغير.."}]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-5', 'al-amal-fil-khatwa', 'published', '2026-10-13T07:00:00Z', '2026-09-08T12:00:00Z', '2026-09-08T12:00:00Z', '{"text":"لَا تَنْتَظِرْ زَوَالَ الْعَتَمَةِ كَيْ تَبْدَأَ، فَالْفَجْرُ لَا يَشْرَقُ إِلَّا لِمَنْ مَشَى فِي لَيْلِهِ صَابِرًا مُتَوَكِّلًا.","plainText":"لا تنتظر زوال العتمة كي تبدأ، فالفجر لا يشرق إلا لمن مشى في ليله صابرا متوكلا.","language":"fusha","author":"شعيب المطوع","topics":["الأمل","البدايات","الصبر"],"behindTheWords":"كثيرون يعلّقون حياتهم على \"حين تنتهي الظروف الصعبة\". الحقيقة أن الحياة تُبنى وسط العاصفة لا بعد انتهائها.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-6', 'darja-khatwa-b-khatwa', 'published', '2026-10-12T07:00:00Z', '2026-09-11T16:40:00Z', '2026-09-11T16:40:00Z', '{"text":"مَا تَحْقَرْشْ الْخَطْوَة الصْغِيرَة.. جْبَالْ كْبِيرَة تْطَلْعَتْ بِحَجْرَة وَرَا حَجْرَة، وَاللِّي نْوَى الْخِيرْ رَبِّي مَاعُمْرُو خَلَّاهْ وَحْدُو.","plainText":"ما تحقرش الخطوة الصغيرة.. جبال كبيرة تطلعت بحجرة ورا حجرة، واللي نوى الخير ربي ماعمرو خلاه وحدو.","language":"darja","author":"شعيب المطوع","topics":["الأمل","البدايات"],"behindTheWords":"تذكير بالبركة الخفية في السعي المتواصل، حتى لو بدت بداياتك متواضعة أمام أعين الناس.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-7', 'al-qalb-al-tayyib', 'published', '2026-10-11T07:00:00Z', '2026-09-14T08:15:00Z', '2026-09-14T08:15:00Z', '{"text":"طِيبَةُ قَلْبِكَ لَيْسَتْ سَذَاجَةً تَخْجَلُ مِنْهَا، هِيَ رِزْقٌ طَاهِرٌ فِي زَمَنٍ جَفَّتْ فِيهِ يَنَابِيعُ النَّقَاءِ.","plainText":"طيبة قلبك ليست سذاجة تخجل منها، هي رزق طاهر في زمن جفت فيه ينابيع النقاء.","language":"fusha","author":"شعيب المطوع","topics":["الطمأنينة","العلاقات"],"behindTheWords":"كثير من الأنقياء يعاتبون أنفسهم حين يُخذلون، ويظنون أن عيبهم كان اللطف. اللطف ليس ضعفًا، بل هو جوهر إنسانيتك.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-8', 'darja-el-niya-tsallak', 'published', '2026-10-10T07:00:00Z', '2026-09-16T19:30:00Z', '2026-09-16T19:30:00Z', '{"text":"النِّيَّة الصَّافْيَة مَا تْخَسَّرْشْ مَوْلَاهَا.. يَمْكِنْ تَبْطَا عَلَيْهَا الْفَرْحَة، بَسَّحْ تْجِي نْهَارْ اللِّي تْجِي كَامْلَة مَكْمُولَة.","plainText":"النية الصافية ما تخسرش مولاها.. يمكن تبطا عليها الفرحة، بسح تجي نهار اللي تجي كاملة مكمولة.","language":"darja","author":"شعيب المطوع","topics":["الطمأنينة","الصبر"],"behindTheWords":"المثل الجزائري الخالد \"دير النية وارقد في الثنية\".. النية الصافية درع يحميك من حيث لا تحتسب.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-9', 'waqt-ar-rahil', 'published', '2026-10-09T07:00:00Z', '2026-09-18T22:10:00Z', '2026-09-18T22:10:00Z', '{"text":"بَعْضُ الْغِيَابِ حَيَاةٌ أُخْرَى، تَعُودُ فِيهَا لِنَفْسِكَ الَّتِي أَهْمَلْتَهَا وَأَنْتَ تُحَاوِلُ تَرْمِيمَ مَنْ لَا يُبَالِي.","plainText":"بعض الغياب حياة أخرى، تعود فيها لنفسك التي أهملتها وأنت تحاول ترميم من لا يبالي.","language":"fusha","author":"شعيب المطوع","topics":["العلاقات","عزّة النفس"],"behindTheWords":"الانسحاب من معارك الاستجداء ليس هزيمة، بل هو النصر الأكبر الذي تهديه لروحك المتعبة.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-10', 'darja-koulchi-b-waqtou', 'published', '2026-10-08T07:00:00Z', '2026-09-20T14:00:00Z', '2026-09-20T14:00:00Z', '{"text":"كُلْشِي فِي وَقْتُو زِينْ.. مَا تْزَرْوِبْشْ الْقِسْمَة قَبْلْ أَوَانْهَا، اللِّي كَتْبُو رَبِّي يَلْحَقْكْ حَتَّى لَوْ كُنْتْ فِي قَاعْ الْبِيرْ.","plainText":"كلشي في وقتو زين.. ما تزربش القسمة قبل أوانها، اللي كتبو ربي يلحقك حتى لو كنت في قاع البير.","language":"darja","author":"شعيب المطوع","topics":["الطمأنينة","الصبر","الأمل"],"behindTheWords":"اليقين بالقدر يسكب في الأنفاس راحة لا يضاهيها شيء. نصيبك لن يأخذه غيرك، فلا تستعجل القلق.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-11', 'sirru-al-kalam', 'published', '2026-10-07T07:00:00Z', '2026-09-22T08:00:00Z', '2026-09-22T08:00:00Z', '{"text":"الْكَلِمَةُ الَّتِي لَا تَبْنِي فِي دَاخِلِكَ مَعْنًى، لَا تَقْضِ عُمْرَكَ وَأَنْتَ تَسْمَعُ صَدَاهَا الْفَارِغَ.","plainText":"الكلمة التي لا تبني في داخلك معنى، لا تقض عمرك وأنت تسمع صداها الفارغ.","language":"fusha","author":"شعيب المطوع","topics":["التأمّل","عزّة النفس"],"behindTheWords":"التلوث السمعي والوعود الجوفاء تستهلك أرواحنا. تعلّم أن تعبر سريعًا عما لا يغذّي قلبك بالصدق.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-12', 'darja-el-sah-f-sah', 'published', '2026-10-06T07:00:00Z', '2026-09-24T17:45:00Z', '2026-09-24T17:45:00Z', '{"text":"مَا يَبْقَى فِي الْوَادْ غِيرْ حْجَارُو.. كُلْ الرِّيحْ وَالزَّعَافْ يَجُوزْ، وَمَا تَبْقَى غِيرْ الْفَعْلَة الزِّينَة وَالْقَلْبْ اللِّي مَا كْذَبْشْ.","plainText":"ما يبقى في الواد غير حجارو.. كل الريح والزعاف يجوز، وما تبقى غير الفعلة الزينة والقلب اللي ما كذبش.","language":"darja","author":"شعيب المطوع","topics":["التأمّل","الصبر"],"behindTheWords":"مثل شعبي جزائري أعيد صياغته برؤية وجدانية: الزبد يذهب جفاءً، والأصيل هو الثابت.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-13', 'jirah-al-ayyam', 'published', '2026-10-05T07:00:00Z', '2026-09-25T11:20:00Z', '2026-09-25T11:20:00Z', '{"text":"الْأَيَّامُ لَا تُشْفِي الْجِرَاحَ تِلْقَائِيًّا، بَلْ تَمْنَحُكَ فَقَطْ اتِّسَاعًا فِي الصَّدْرِ لِتَتَعَلَّمَ كَيْفَ تَعِيشُ مَعَهَا دُونَ أَنْ تَنْزِفَ مَرَّةً أُخْرَى.","plainText":"الأيام لا تشفي الجراح تلقائيا، بل تمنحك فقط اتساعا في الصدر لتتعلم كيف تعيش معها دون أن تنزف مرة أخرى.","language":"fusha","author":"شعيب المطوع","topics":["الطمأنينة","الصبر"],"behindTheWords":"الندبات لا تختفي كليًا، بل تتحول إلى أوسمة نضج تخبرك أنك مررت بالنار وخرجت منها سالم الروح.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-14', 'darja-el-ghorba', 'published', '2026-10-04T07:00:00Z', '2026-09-27T21:15:00Z', '2026-09-27T21:15:00Z', '{"text":"الْغُرْبَة مَاشِي بْعَادْ الْأَمْيَالْ.. الْغُرْبَة نْهَارْ تْكُونْ وَسْطْ نَاسَكْ وَمَا يَلْقَاوْشْ لِيكْ كَلِمَة تْفَهْمَكْ.","plainText":"الغربة ماشي بعاد الأميال.. الغربة نهار تكون وسط ناسك وما يلقاوش ليك كلمة تفهمك.","language":"darja","author":"شعيب المطوع","topics":["الغربة والحنين","العلاقات"],"behindTheWords":"عن الاغتراب الروحي والنفسي، حين تشعر بوحشة المسافة حتى وأنت جالس في منزلك.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-15', 'daw-an-nafs', 'published', '2026-10-03T07:00:00Z', '2026-09-29T13:00:00Z', '2026-09-29T13:00:00Z', '{"text":"كُنْ لِنَفْسِكَ نُورًا كُلَّمَا انْطَفَأَتْ مَنَارَاتُ الْآخَرِينَ، فَالَّذِي يَنْتَظِرُ شُعْلَةً مِنْ يَدِ غَيْرِهِ قَدْ يَمُوتُ بَرْدًا.","plainText":"كن لنفسك نورا كلما انطفأت منارات الآخرين، فالذي ينتظر شعلة من يد غيره قد يموت بردا.","language":"fusha","author":"شعيب المطوع","topics":["عزّة النفس","الأمل"],"behindTheWords":"الاعتماد على إشادة المحيطين وقود سريع النفاد. غَذِّ شعلتك بإيمانك الداخلي ورسالتك الشخصية.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-16', 'darja-rabbi-kbir', 'published', '2026-10-02T07:00:00Z', '2026-10-01T15:10:00Z', '2026-10-01T15:10:00Z', '{"text":"ضَايْقَة ضَايْقَة.. وَفَجْأَة يَفْتَحْ رَبِّي بَابْ كُنْتْ حَاسْبُو حِيطْ. سُبْحَانْ اللِّي مَا يَنْسَى عَبْدُو.","plainText":"ضايقة ضايقة.. وفجأة يفتح ربي باب كنت حاسبو حيط. سبحان اللي ما ينسى عبدو.","language":"darja","author":"شعيب المطوع","topics":["الأمل","الطمأنينة","الصبر"],"behindTheWords":"لحظة الفرج التي تباغت الإنسان في أشد أوقات انسداد الأفق.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-17', 'fasl-al-bidayat', 'published', '2026-10-01T07:00:00Z', '2026-10-02T10:00:00Z', '2026-10-02T10:00:00Z', '{"text":"كُلُّ نِهَايَةٍ صَادِقَةٍ تَحْمِلُ فِي أَحْشَائِهَا بَذْرَةَ انْبِثَاقٍ أَعْظَمَ، فَلَا تَبْكِ عَلَى بَابٍ أُغْلِقَ لِيَحْمِيَكَ مِنْ مَسَارٍ لَا يُشْبِهُكَ.","plainText":"كل نهاية صادقة تحمل في أحشائها بذرة انبثاق أعظم، فلا تبك على باب أغلق ليحميك من مسار لا يشبهك.","language":"fusha","author":"شعيب المطوع","topics":["البدايات","الأمل","التأمّل"],"behindTheWords":"الأقدار ترحمنا بالمنع كما ترحمنا بالعطاء، ولكن قصر نظرنا يجعلنا نتحسر على ما نجّانا الله منه.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-18', 'darja-el-qadr-ghali', 'published', '2026-09-30T07:00:00Z', '2026-10-03T18:00:00Z', '2026-10-03T18:00:00Z', '{"text":"اللِّي عَاشْ بَالْقَدْرْ يَمُوتْ رَاسُو مَرْفُوعْ.. مَاشِي شَرْطْ تْرْضِي كُلْ النَّاسْ، الْمُهِمْ كِي تْحُطْ رَاسَكْ عَلَى الْمَخَدَّة تْرْقُدْ هَانِي.","plainText":"اللي عاش بالقدر يموت راسو مرفوع.. ماشي شرط ترضي كل الناس، المهم كي تحط راسك على المخدة ترقد هاني.","language":"darja","author":"شعيب المطوع","topics":["عزّة النفس","الطمأنينة"],"behindTheWords":"راحة الضمير هي الوسادة الأنعم في هذا العالم الصاخب.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-19', 'wihdat-al-fikr', 'published', '2026-09-29T07:00:00Z', '2026-10-04T08:30:00Z', '2026-10-04T08:30:00Z', '{"text":"الْعُزْلَةُ لَيْسَتْ هُرُوبًا مِنَ الْعَالَمِ، بَلْ هِيَ اسْتِرْدَادٌ لِلذَّاتِ قَبْلَ أَنْ تَذُوبَ فِي ضَجِيجِ الْآخَرِينَ.","plainText":"العزلة ليست هروبا من العالم، بل هي استرداد للذات قبل أن تذوب في ضجيج الآخرين.","language":"fusha","author":"شعيب المطوع","topics":["التأمّل","الطمأنينة"],"behindTheWords":"الخلوة مع النفس صيانة ضرورية للوعي، بها نعيد فرز مشاعرنا وتنظيف مرايانا الداخلية.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-20', 'darja-koul-sahaba', 'published', '2026-09-28T07:00:00Z', '2026-10-05T12:00:00Z', '2026-10-05T12:00:00Z', '{"text":"مَا كَاشْ سْحَابَة دَامَتْ.. حَتَّى الْغِيمْ الْكْحَلْ كِي يَنْزَلْ يْخَلِّي مَوْرَاهْ رِيحَة تْرَابْ تْرُدْ الرُّوحْ.","plainText":"ما كاش سحابة دامت.. حتى الغيم الكحل كي ينزل يخلي موراه ريحة تراب ترد الروح.","language":"darja","author":"شعيب المطوع","topics":["الأمل","الصبر"],"behindTheWords":"عن جمال ما بعد الشدائد، كما تعبق الأرض برائحة الغيث بعد رعودها.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-21', 'sidq-al-mashaer', 'published', '2026-09-27T07:00:00Z', '2026-10-06T14:40:00Z', '2026-10-06T14:40:00Z', '{"text":"الصِّدْقُ لَا يَمْلِكُ زُخْرُفَ الْكَلَامِ، لَكِنَّهُ يَسْكُنُ الْقَلْبَ كَالنَّقْشِ عَلَى الْحَجَرِ لَا يَمْحُوهُ الزَّمَانُ.","plainText":"الصدق لا يملك زخرف الكلام، لكنه يسكن القلب كالنقش على الحجر لا يمحوه الزمان.","language":"fusha","author":"شعيب المطوع","topics":["العلاقات","التأمّل"],"behindTheWords":"الكلمة الصادقة بسيطة، لا تحتاج إلى تزيين مبالغ فيه لتصل؛ نورها ينفذ بذاته.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-22', 'darja-qalbek-el-kebir', 'published', '2026-09-26T07:00:00Z', '2026-10-07T16:00:00Z', '2026-10-07T16:00:00Z', '{"text":"قَلْبَكْ الْكْبِيرْ مَا يْضَيَّعُوشْ رَبِّي.. نَاسْ يْشُوفُوهْ ضُعْفْ، وَرَبِّي شَايْفُو بَرَكَة رَاحْ تْفِيضْ عَلَيْكْ نْهَارْ تَحْتَاجْهَا.","plainText":"قلبك الكبير ما يضيعوش ربي.. ناس يشوفوه ضعف، وربي شايفو بركة راح تفيض عليك نهار تحتاجها.","language":"darja","author":"شعيب المطوع","topics":["الطمأنينة","العلاقات"],"behindTheWords":"رسالة إسناد لكل من يشعر بأن طيبته استُغلت في معترك الحياة.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-23', 'thabat-fil-mihan', 'published', '2026-09-25T07:00:00Z', '2026-10-08T09:15:00Z', '2026-10-08T09:15:00Z', '{"text":"تَعَلَّمْ كَيْفَ تَكُونُ كَالشَّجَرَةِ الْبَاسِقَةِ؛ تَتَمَايَلُ مَعَ الرِّيَاحِ كَيْ لَا تَنْكَسِرَ، لَكِنَّ جُذُورَهَا تَمْسَكُ أَعْمَاقَ الْأَرْضِ.","plainText":"تعلم كيف تكون كالشجرة الباسقة؛ تتمايل مع الرياح كي لا تنكسر، لكن جذورها تمسك أعماق الأرض.","language":"fusha","author":"شعيب المطوع","topics":["الصبر","عزّة النفس"],"behindTheWords":"المرونة الواعية هي سر البقاء، تختلف تمامًا عن التنازل عن المبادئ.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-24', 'darja-sahbi-el-ghali', 'published', '2026-09-24T07:00:00Z', '2026-10-09T19:00:00Z', '2026-10-09T19:00:00Z', '{"text":"الصَّاحَبْ الْحَقِيقِي مَاشِي اللِّي يَسْأَلْ عَلَيْكْ غِيرْ كِي يْكُونْ مُحْتَاجْ.. الصَّاحَبْ هُوَ اللِّي كِي تْظْلَامْ الدَّنْيَا فِي عِينَيْكْ تَلْقَاهْ شَادْلَكْ يَدَّكْ سَاكَتْ.","plainText":"الصاحب الحقيقي ماشي اللي يسأل عليك غير كي يكون محتاج.. الصاحب هو اللي كي تظلام الدنيا في عينيك تلقاه شادلك يدك ساكت.","language":"darja","author":"شعيب المطوع","topics":["العلاقات","الطمأنينة"],"behindTheWords":"المواقف وحدها تكشف معادن الرفقة، والصمت المشفق أبلغ من مئات العبارات المزيّفة.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-25', 'waza-al-khawatir', 'published', '2026-09-23T07:00:00Z', '2026-10-10T11:00:00Z', '2026-10-10T11:00:00Z', '{"text":"جَبْرُ الْخَوَاطِرِ دَيْنٌ مَرْدُودٌ؛ تَزْرَعُهُ الْيَوْمَ فِي قَلْبٍ مَكْسُورٍ، فَيَحْصُدُهُ قَلْبُكَ غَدًا عِنْدَمَا تَشْتَدُّ عَلَيْكَ الْأَيَّامُ.","plainText":"جبر الخواطر دين مردود؛ تزرعه اليوم في قلب مكسور، فيحصده قلبك غدا عندما تشتد عليك الأيام.","language":"fusha","author":"شعيب المطوع","topics":["الطمأنينة","العلاقات","الأمل"],"behindTheWords":"صنائع المعروف تقي مصارع السوء، ومن جبر خواطر الناس جبر الله قلبه بحكمته.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-26', 'darja-asber-tenal', 'published', '2026-09-22T07:00:00Z', '2026-10-11T13:20:00Z', '2026-10-11T13:20:00Z', '{"text":"اصْبُرْ تَنَالْ.. الْغَلْيَانْ يْرَيَّبْ الْقِدْرَة، وَالْعَقْلْ الرَّزِينْ يَجِيبْ حَقُّو بْلَا عْيَاطْ وَلَا خْسَارَة دَمْ.","plainText":"اصبر تنال.. الغليان يريب القدرة، والعقل الرزين يجيب حقو بلا عياط ولا خسارة دم.","language":"darja","author":"شعيب المطوع","topics":["الصبر","عزّة النفس"],"behindTheWords":"الحكمة الشعبية في ضبط الغضب، والهدوء الاستراتيجي في مواجهة التحديات.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-27', 'sharaf-al-muhawala', 'published', '2026-09-21T07:00:00Z', '2026-10-12T07:45:00Z', '2026-10-12T07:45:00Z', '{"text":"لَيْسَ الْفَشَلُ أَنْ تَعْثُرَ خُطْوَتُكَ، بَلْ أَنْ تَرْضَى بِالسُّقُوطِ سَقْفًا لِأَحْلَامِكَ دُونَ أَنْ تُعَاوِدَ الْوُقُوفَ.","plainText":"ليس الفشل أن تعثر خطوتك، بل أن ترضى بالسقوط سقفا لأحلامك دون أن تعاود الوقوف.","language":"fusha","author":"شعيب المطوع","topics":["البدايات","الأمل","الصبر"],"behindTheWords":"العثرات درجات في سلم التعلم، ولا يهزم الإنسان إلا إذا أعلن استسلامه من الداخل.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-28', 'darja-el-weld-el-har', 'published', '2026-09-20T07:00:00Z', '2026-10-13T17:15:00Z', '2026-10-13T17:15:00Z', '{"text":"الْحُرْ كِي يَنْضَرّ يَبْتَسَمْ فِي وَجْهْ النَّاسْ، وَكِي يَخْلَى بْرُوحُو يَرْفَعْ يَدُّو لِلْعَالِي.. الشَّكْوَى لِغِيرْ رَبِّي مَذَلَّة.","plainText":"الحر كي ينضر يبتسم في وجه الناس، وكي يخلى بروحو يرفع يدو للعالي.. الشكوى لغير ربي مذلة.","language":"darja","author":"شعيب المطوع","topics":["عزّة النفس","الطمأنينة"],"behindTheWords":"عزة النفس عند الألم والشكوى إلى الخالق وحده، خصلة أصيلة في الشخصية الجزائرية.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-29', 'al-amal-ar-raqiy', 'published', '2026-09-19T07:00:00Z', '2026-10-14T08:00:00Z', '2026-10-14T08:00:00Z', '{"text":"كُلَّمَا زَادَتْ غُرْبَتُكَ بَيْنَ النَّاسِ، اعْلَمْ أَنَّ رُوحَكَ تَطْلُبُ مَرَاقِيَ لَا يَبْلُغُهَا سِوَى مَنْ أَلِفَ الْحَقَّ وَأَوْحَشَهُ الزَّيْفُ.","plainText":"كلما زادت غربتك بين الناس، اعلم أن روحك تطلب مراقي لا يبلغها سوى من ألف الحق وأوحشه الزيف.","language":"fusha","author":"شعيب المطوع","topics":["التأمّل","عزّة النفس","الغربة والحنين"],"behindTheWords":"الشعور بالغربة قد يكون دليلاً على صفاء الفطرة ورفض الانصياع للابتذال السائد.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-30', 'darja-khatima-el-khir', 'published', '2026-09-18T07:00:00Z', '2026-10-14T19:30:00Z', '2026-10-14T19:30:00Z', '{"text":"دِيرْ الْخِيرْ وَانْسَاهْ.. الدَّنْيَا دَوَّارَة، وَالْحَبَّة اللِّي تَرْمِيهَا فِي أَرْضْ نْقِيَّة رَاحْ تَرْجَعْلَكْ جْنَانْ نْهَارْ تَعْطَشْ.","plainText":"دير الخير وانساه.. الدنيا دوارة، والحبة اللي ترميها في أرض نقية راح ترجعلك جنان نهار تعطش.","language":"darja","author":"شعيب المطوع","topics":["الطمأنينة","العلاقات","الأمل"],"behindTheWords":"عطاء بلا منّ ولا انتظار شكر، لأن الخير الحقيقي يعود لفاعله بصور لا تخطر له على بال.","revisions":[]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-31', 'draft-al-watan', 'scheduled', '2026-10-20T07:00:00Z', '2026-10-15T11:00:00Z', '2026-10-15T11:00:00Z', '{"text":"فِي هَوَى الْوَطَنِ لَا نَبْحَثُ عَنْ كَمَالِ التُّرَابِ، بَلْ عَنْ ذَلِكَ النَّبْضِ الَّذِي يَشُدُّنَا إِلَيْهِ رَغْمَ الْجِرَاحِ.","plainText":"في هوى الوطن لا نبحث عن كمال التراب، بل عن ذلك النبض الذي يشدنا إليه رغم الجراح.","language":"fusha","author":"شعيب المطوع","topics":["الغربة والحنين","التأمّل"],"behindTheWords":"مسودة مجدولة للنشر القادم تتناول عمق الانتماء الوطني النقي.","revisions":[{"id":"rev-w1","timestamp":"2026-10-15T11:00:00Z","note":"مسودة مجدولة للنشر في 20 أكتوبر","textSnippet":"في هوى الوطن لا نبحث.."}]}');
INSERT OR IGNORE INTO quotes (id, slug, status, published_at, created_at, updated_at, data) VALUES ('quote-32', 'draft-darja-bladna', 'draft', '2026-10-22T07:00:00Z', '2026-10-15T11:30:00Z', '2026-10-15T11:30:00Z', '{"text":"بْلَادِي وَإِنْ جَارَتْ عَلَيَّ عَزِيزَة.. رِيحَة أُمِّي فِي حْوَارِيهَا، وَصَوْتْ الْأَذَانْ فِيهَا يَرُدّ فِينَا الرُّوحْ.","plainText":"بلادي وإن جارت علي عزيزة.. ريحة أمي في حواريها، وصوت الأذان فيها يرد فينا الروح.","language":"darja","author":"شعيب المطوع","topics":["الغربة والحنين"],"behindTheWords":"مسودة قيد المراجعة للخواطر الجزائرية القادمة.","revisions":[{"id":"rev-b1","timestamp":"2026-10-15T11:30:00Z","note":"المسودة الأولى قيد التنقيح","textSnippet":"بلادي وإن جارت علي عزيزة.."}]}');
